```vue /home/codx-junior-projects/codx-junior/client/src/components/global_settings/plugins/PluginsEditor.vue
<script setup>
// Import any necessary modules here
</script>

<template>
  <div class="w-full h-full flex flex-col gap-2">
    <h1 class="text-2xl font-bold">Plugins</h1>
    <!-- Form to Add New Plugin -->
    <div class="flex flex-col gap-2">
      <input v-model="newPlugin.name" type="text" placeholder="Plugin Name" class="input input-bordered" />
      <input v-model="newPlugin.module_path" type="text" placeholder="Module Path" class="input input-bordered" />
      <input v-model="newPlugin.plugin_path" type="text" placeholder="Plugin Path" class="input input-bordered" />

      <!-- New Input for Plugin Folder Path -->
      <input v-model="folderPath" type="text" placeholder="Plugin Folder Path" class="input input-bordered" />

      <div class="flex gap-2 items-center">
        <button @click="addPlugin" class="btn btn-primary">Add Plugin</button>
        <button @click="clearNewPlugin" class="btn btn-secondary">Clear</button>
        <button @click="toggleMode" class="btn btn-secondary">Toggle View</button>
        <!-- Button to Load Plugin from Folder -->
        <button @click="loadFromFolder" class="btn btn-info">Load from Folder</button>
      </div>
    </div>

    <!-- List of Plugins -->
    <ul class="list-disc">
      <li v-for="plugin in plugins" :key="plugin.name" class="flex justify-between items-center">
        <span>{{ plugin.name }}</span>
        <button @click="removePlugin(plugin.name)" class="btn btn-error">Remove</button>
      </li>
    </ul>
  </div>
</template>

<script>
export default {
  data() {
    return {
      plugins: [],
      newPlugin: {
        name: '',
        module_path: '',
        plugin_path: '',
        method: '',
        arguments: [],
        roles: [],
        extends: []
      },
      folderPath: '', // Variable to store the folder path
      isListMode: true
    }
  },
  methods: {
    async loadPlugins() {
      this.plugins = await this.$storex.api.settings.global.plugins.list()
    },
    async addPlugin() {
      await this.$storex.api.plugins.add(this.newPlugin)
      await this.loadPlugins()
      this.clearNewPlugin()
    },
    async removePlugin(pluginName) {
      await this.$storex.api.plugins.remove(pluginName)
      await this.loadPlugins()
    },
    clearNewPlugin() {
      this.newPlugin = {
        name: '',
        module_path: '',
        plugin_path: '',
        method: '',
        arguments: [],
        roles: [],
        extends: []
      }
    },
    toggleMode() {
      this.isListMode = !this.isListMode
    },
    async loadFromFolder() {
      // Logic to load plugins from folderPath
      if(this.folderPath) {
        const loadedPlugins = await this.$storex.api.plugins.loadFromFolder(this.folderPath)
        this.plugins = [...this.plugins, ...loadedPlugins]
        this.folderPath = '' // Clear folder path after loading
      }
    }
  },
  mounted() {
    this.loadPlugins()
  }
}
</script>
```

