### Vue.js Component: PluginModal.vue

This component provides a detailed view of the plugin where users can edit parameters and confirm plugin deletion.

```vue /home/codx-junior-projects/codx-junior/client/src/components/global_settings/plugins/PluginModal.vue
<script setup>
import { ref } from 'vue'
import { API } from '@/api/api'

// Accepting plugin as a property
defineProps(['plugin'])

// Define the close event to control parent component states
const emit = defineEmits(['close', 'pluginUpdated'])

// Editable plugin data for default_value changes
const editablePlugin = ref({ ...plugin })
const confirmDeletion = ref(false)

// Function to update the plugin on save
async function updatePlugin() {
  await API.plugins.add(editablePlugin.value)
  emit('pluginUpdated')
  emit('close')
}

// Function to remove plugin
async function removePlugin() {
  if (confirmDeletion.value) {
    await API.plugins.remove(plugin.name)
    emit('pluginUpdated')
  } else {
    confirmDeletion.value = true
  }
}

</script>

<template>
  <div class="modal">
    <div class="modal-box">
      <h2 class="text-lg font-bold mb-2">{{ plugin.name }}</h2>
      <!-- Editable plugin details -->
      <div v-for="arg in editablePlugin.arguments" :key="arg.name" class="mb-2">
        <label class="block">{{ arg.name }}</label>
        <input v-model="arg.default_value" type="text" class="input input-bordered w-full" />
      </div>
      <div class="modal-action">
        <button @click="updatePlugin" class="btn btn-success">Save Changes</button>
        <button @click="removePlugin" class="btn btn-error">{{ confirmDeletion ? "Confirm Deletion?" : "Delete" }}</button>
        <button @click="emit('close')" class="btn">Close</button>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  methods: {
    // Plugin update and delete methods
  }
}
</script>
```

